57	static constexpr std::string_view kUsage = R"(
58	Takes in an IR file and produces an IR file that has been run through the
59	standard optimization pipeline.
60	
61	Successfully optimized IR is printed to stdout.
62	
63	Expected invocation:
64	  opt_main <IR file>
65	where:
66	  - <IR file> is the path to the input IR file. '-' denotes stdin as input.
67	
68	Example invocation:
69	  opt_main path/to/file.ir
70	)";
71	
72	ABSL_FLAG(std::string, output_path, "-",
73	          "Output path for the optimized IR file; '-' denotes stdout.");
74	ABSL_FLAG(std::optional<std::string>, alsologto, std::nullopt,
75	          "Path to write logs to, in addition to stderr.");
76	
77	ABSL_FLAG(bool, list_passes, false,
78	          "If passed list the names of all passes and exit.");
