80	// Flags for injecting additional passes into the pipeline for
81	// bisect/investigation.
82	ABSL_FLAG(std::optional<std::string>, bisect_inject_passes, std::nullopt,
83	          "If passed, inject these passes into the pipeline immediately before "
84	          "the --bisect_inject_passes_count pass runs. This flag takes options "
85	          "in the same format as the --passes flag. It can use compound passes "
86	          "defined in the --pipeline_proto flag.");
87	ABSL_FLAG(std::optional<int64_t>, bisect_inject_passes_count, std::nullopt,
88	          "If passed, inject passes from --bisect_inject_passes after this "
89	          "many passes have run.");
